import { glob } from 'astro/loaders';

/**
 * `docs` collection — every .md/.mdx file under src/content/docs/ becomes a
 * documentation page at /docs/<slug>.  Add a file → add a page.
 *
 * Required frontmatter:
 *   title         Plain string; used as <title>, sidebar link, and prev/next label.
 *   description   ≤ 160 chars; used as meta description and in the docs index card.
 *
 * Optional frontmatter:
 *   section   Sidebar group label — must be one of the canonical sections in
 *             src/utils/docs.ts#SECTION_ORDER (Getting Started | Core Concepts |
 *             How It Works | Reference | Migration).  Unlisted sections sort last.
 *   order     Numeric sort position within its section (lower = earlier).
 *             Pages without an order sort after ordered ones (treated as 999).
 *   draft     When true the page is excluded from the build and the sitemap.
 *             Default: false.
 *   tags      Free-form topic tags for future filtering / related-docs UI.
 *   updated   ISO-8601 date of last significant content revision (YYYY-MM-DD).
 *             Used by the TechArticle JSON-LD block and a "Last updated" note.
 */
const docs = defineCollection({
  loader: glob({ pattern: '**/*.{md,mdx}', base: './src/content/docs' }),
  schema: z.object({
    title: z.string(),
    description: z.string().max(175), // Google truncates ~155–160; 175 gives headroom for edge pages
    section: z.string().optional(),
    order: z.number().optional(),
    draft: z.boolean().default(false),
    tags: z.array(z.string()).optional(),
    updated: z.coerce.date().optional(),
  }),
});

/**
 * `pages` collection — standalone marketing/content pages (about, features, …).
 * Rendered via custom page templates in src/pages/, not via a dynamic route.
 * Kept here so their content lives in markdown and is schema-validated.
 */
const pages = defineCollection({
  loader: glob({ pattern: '**/*.{md,mdx}', base: './src/content/pages' }),
  schema: z.object({
    title: z.string(),
    description: z.string().optional(),
  }),
});

export const collections = { docs, pages };
