 * Docs collection utilities — shared across DocsSidebar, DocsPrevNext, and
 * the docs index page to guarantee a consistent canonical order.
 *
 * Section taxonomy (matches seo-foundation.md §4.5 and ASTRO-SCAFFOLD-NOTES.md):
 *
 *   Getting Started  — install, quick-start
 *   Core Concepts    — architecture, specialists, skills, lifecycle
 *   How It Works     — context-assembly, self-evolution, cost-and-tiering, wiki-pattern
 *   Reference        — configuration, commands, status-line
 *   Migration        — migration notes
 *
 * Unknown sections (not in this list) sort after all known ones, alphabetically.
 */

/** Canonical display order for doc sections. */
export const SECTION_ORDER: readonly string[] = [
  'Getting Started',
  'Core Concepts',
  'How It Works',
  'Reference',
  'Migration',
];

/** Returns the sort index for a section name (unknown → after last known). */
function sectionRank(section: string | undefined): number {
  const name = section ?? '';
  const i = SECTION_ORDER.indexOf(name);
  return i === -1 ? SECTION_ORDER.length : i;
}

/**
 * Comparator for doc entries.  Sort by:
 *   1. Section rank (canonical SECTION_ORDER above)
 *   2. `order` frontmatter within that section (lower = earlier; missing → 999)
 *   3. Title alphabetically as a stable tiebreaker
 */
export function compareDocs(
  a: { data: { section?: string; order?: number; title: string } },
  b: { data: { section?: string; order?: number; title: string } },
): number {
  const sectionCmp = sectionRank(a.data.section) - sectionRank(b.data.section);
  if (sectionCmp !== 0) return sectionCmp;
  const orderCmp = (a.data.order ?? 999) - (b.data.order ?? 999);
  if (orderCmp !== 0) return orderCmp;
  return a.data.title.localeCompare(b.data.title);
