function sortRows(rows: RunsListRow[], sort: SortState): RunsListRow[] {
  const out = [...rows];
  out.sort((a, b) => {
    const av = a[sort.key];
    const bv = b[sort.key];
    if (av === bv) return 0;
    const cmp = av > bv ? 1 : -1;
    return sort.dir === "asc" ? cmp : -cmp;
